import{_ as t,o as r,c as o,ag as s}from"./chunks/framework.BZohXCq9.js";const p=JSON.parse('{"title":"Student Dashboard -> Search Instructors (deep)","description":"","frontmatter":{},"headers":[],"relativePath":"modules/student-dashboard/search-instructors.md","filePath":"modules/student-dashboard/search-instructors.md"}'),i={name:"modules/student-dashboard/search-instructors.md"};function a(d,e,l,n,c,u){return r(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="student-dashboard-search-instructors-deep" tabindex="-1">Student Dashboard -&gt; Search Instructors (deep) <a class="header-anchor" href="#student-dashboard-search-instructors-deep" aria-label="Permalink to &quot;Student Dashboard -&gt; Search Instructors (deep)&quot;">​</a></h1><p><strong>Module:</strong> <code>student-dashboard</code><br><strong>Feature:</strong> <code>search-instructors</code><br><strong>Routes:</strong> <code>/student-dashboard/search</code>, <code>/student-dashboard/search/instructors/:id</code></p><p>This feature covers student-side instructor discovery and the transition from browsing to booking. It includes the search/list page, filter controls, map/list views, and the instructor detail surface where slot/package selection begins.</p><h2 id="purpose" tabindex="-1">Purpose <a class="header-anchor" href="#purpose" aria-label="Permalink to &quot;Purpose&quot;">​</a></h2><ul><li>Let students browse instructors who are eligible for booking.</li><li>Filter by geography, radius, transmission, gender, price, rating, and availability dates.</li><li>Show instructor summary information and map context.</li><li>Drill into a specific instructor profile and start the lesson booking/payment flow.</li></ul><h2 id="frontend-files" tabindex="-1">Frontend files <a class="header-anchor" href="#frontend-files" aria-label="Permalink to &quot;Frontend files&quot;">​</a></h2><table tabindex="0"><thead><tr><th>File</th><th>Role</th><th>Integration</th></tr></thead><tbody><tr><td><code>Frontend/src/pages/private/student-dashboard/searchInstructor.tsx</code></td><td>Route entry for search</td><td>Thin wrapper for the instructor-discovery UI.</td></tr><tr><td><code>Frontend/src/components/ProfessionalInstructor/InstructorInfo.tsx</code></td><td>Main search/discovery implementation</td><td>Calls instructor public queries; manages filters, location, map/list rendering, and navigation to instructor detail.</td></tr><tr><td><code>Frontend/src/components/FilterPopover.tsx</code></td><td>Filter UI</td><td>Collects radius, address, rating, gender, transmission, price, and date filters.</td></tr><tr><td><code>Frontend/src/components/AddressSearch.tsx</code></td><td>Address search helper</td><td>Supports geocoded location input used by the filter flow.</td></tr><tr><td><code>Frontend/src/pages/public/OurInstructor.tsx</code></td><td>Instructor detail route entry</td><td>Mounts instructor detail surface from the student route.</td></tr><tr><td><code>Frontend/src/components/InstructorComponent/PostSummary.tsx</code></td><td>Instructor detail shell</td><td>Loads instructor profile, slots/packages, and review snippets.</td></tr><tr><td><code>Frontend/src/components/InstructorComponent/Availability.tsx</code></td><td>Availability picker</td><td>Lets students inspect/select slots before booking.</td></tr><tr><td><code>Frontend/src/components/InstructorComponent/Summary.tsx</code></td><td>Detail summary</td><td>Shows instructor info, pricing, and booking CTA context.</td></tr><tr><td><code>Frontend/src/components/InstructorComponent/BulkPackageCard.tsx</code></td><td>Package display</td><td>Shows bulk lesson/package options where available.</td></tr><tr><td><code>Frontend/src/components/StudentComponents/InstructorReviews.tsx</code></td><td>Student-facing reviews</td><td>Shows instructor review content on the detail page.</td></tr></tbody></table><h2 id="frontend-graphql" tabindex="-1">Frontend GraphQL <a class="header-anchor" href="#frontend-graphql" aria-label="Permalink to &quot;Frontend GraphQL&quot;">​</a></h2><h3 id="instructor-discovery-public-profile" tabindex="-1">Instructor discovery / public profile <a class="header-anchor" href="#instructor-discovery-public-profile" aria-label="Permalink to &quot;Instructor discovery / public profile&quot;">​</a></h3><ul><li>File: <code>Frontend/src/graphql/mutations/instructorPublic.ts</code></li><li>Operations used by this surface include: <ul><li><code>getNearbyInstructors(filter, offset, limit)</code></li><li><code>getInstructorPublicProfile(id)</code></li></ul></li><li>Used by: <ul><li><code>InstructorInfo.tsx</code> for instructor search list</li><li><code>PostSummary.tsx</code> / detail page for selected instructor data</li></ul></li></ul><h3 id="reviews" tabindex="-1">Reviews <a class="header-anchor" href="#reviews" aria-label="Permalink to &quot;Reviews&quot;">​</a></h3><ul><li>File: <code>Frontend/src/graphql/Queries/ReviewQueries.ts</code></li><li>Relevant operation: <ul><li><code>GET_INSTRUCTOR_REVIEWS</code></li></ul></li><li>Used by: <ul><li><code>InstructorReviews.tsx</code></li><li>detail page review display</li></ul></li></ul><h3 id="student-context-helpers" tabindex="-1">Student context helpers <a class="header-anchor" href="#student-context-helpers" aria-label="Permalink to &quot;Student context helpers&quot;">​</a></h3><ul><li>File: <code>Frontend/src/graphql/mutations/studentProfile.ts</code></li><li>Used for student profile/address context where discovery flow needs current student data.</li></ul><h2 id="backend-schema" tabindex="-1">Backend schema <a class="header-anchor" href="#backend-schema" aria-label="Permalink to &quot;Backend schema&quot;">​</a></h2><h3 id="typedefs" tabindex="-1">TypeDefs <a class="header-anchor" href="#typedefs" aria-label="Permalink to &quot;TypeDefs&quot;">​</a></h3><ul><li>File: <code>server/src/graphql/typeDefs/instructorPublic.typeDefs.js</code></li><li>Relevant query fields: <ul><li><code>getNearbyInstructors(filter, offset, limit)</code></li><li><code>getInstructorPublicProfile(id)</code></li></ul></li><li>Related types: <ul><li>instructor summary/detail shapes</li><li>availability info</li><li>tariff/package fields</li></ul></li><li>File: <code>server/src/graphql/typeDefs/ReviewTypes.js</code><ul><li>provides review types used by <code>getInstructorReviews</code></li></ul></li></ul><h3 id="resolvers" tabindex="-1">Resolvers <a class="header-anchor" href="#resolvers" aria-label="Permalink to &quot;Resolvers&quot;">​</a></h3><ul><li>File: <code>server/src/graphql/resolvers/instructorPublic.resolver.js</code></li><li>Relevant resolvers: <ul><li><code>Query.getNearbyInstructors</code><ul><li>Applies geographic and non-geographic filters.</li><li>Reads tariff, availability, profile-completion, and verification state.</li></ul></li><li><code>Query.getInstructorPublicProfile</code><ul><li>Returns a single instructor’s full public profile, tariff, and availability context.</li></ul></li></ul></li><li>File: <code>server/src/graphql/resolvers/Review.resolver.js</code><ul><li><code>Query.getInstructorReviews</code><ul><li>Returns rating/review rows for display on the public/student detail page.</li></ul></li></ul></li></ul><h2 id="main-backend-dependencies" tabindex="-1">Main backend dependencies <a class="header-anchor" href="#main-backend-dependencies" aria-label="Permalink to &quot;Main backend dependencies&quot;">​</a></h2><table tabindex="0"><thead><tr><th>File</th><th>Role</th></tr></thead><tbody><tr><td><code>server/src/models/User.js</code></td><td>Instructor profile/discovery source</td></tr><tr><td><code>server/src/models/teacherTariff.model.js</code></td><td>Lesson price and package data</td></tr><tr><td><code>server/src/models/teacherAvailability.model.js</code></td><td>Instructor availability and bookable slots</td></tr><tr><td><code>server/src/models/Reviews.js</code></td><td>Student-to-instructor review data</td></tr></tbody></table><h2 id="data-flow" tabindex="-1">Data flow <a class="header-anchor" href="#data-flow" aria-label="Permalink to &quot;Data flow&quot;">​</a></h2><ol><li>Student opens <code>/student-dashboard/search</code>.</li><li>Search page obtains coordinates/address context and filter selections.</li><li><code>getNearbyInstructors</code> returns filtered instructor cards.</li><li>Student clicks into an instructor, navigating to <code>/student-dashboard/search/instructors/:id</code>.</li><li>Detail route loads public instructor profile, availability, pricing/packages, and instructor reviews.</li><li>Student selects lesson slots/package and continues into the booking/checkout flow owned by the booked-lessons module.</li></ol><h2 id="developer-notes" tabindex="-1">Developer notes <a class="header-anchor" href="#developer-notes" aria-label="Permalink to &quot;Developer notes&quot;">​</a></h2><ul><li>Discovery is filter/geolocation based, not a full-text directory search.</li><li>Booking readiness depends on instructor Stripe/payment readiness on the backend; the detail page surfaces this by disabling or gating booking actions.</li><li><code>searchInstructor.tsx</code> is mainly a route shell; most behavior lives inside <code>InstructorInfo.tsx</code>.</li></ul>',25)])])}const b=t(i,[["render",a]]);export{p as __pageData,b as default};
